//! Tests for type checker (tests2 lift expr).
//
// Generated by splitting tc/tests2.rs into submodules for maintainability.

use super::*;

fn binder_body(e: &Expr) -> &Expr {
    match &e.kind {
        ExprKind::Lam(_, _, b) | ExprKind::Pi(_, _, b) | ExprKind::Let(_, _, _, b, _) => b.as_ref(),
        _ => panic!("Expected binder, got {e:?}"),
    }
}

#[test]
fn test_lift_expr_cutoff_plus_one() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);
    let bv = |n| Expr::from_kind(ExprKind::BVar(n));

    // λ x. BVar(0) lifted at cutoff 0 by 5 — bound, NOT lifted
    let r = tc.lift_expr(&Expr::lam(BinderInfo::Default, Expr::prop(), bv(0)), 0, 5);
    assert_eq!(
        binder_body(&r),
        &bv(0),
        "BVar(0) under lam should NOT be lifted"
    );

    // λ x. BVar(1) — free, lifted to BVar(6)
    let r = tc.lift_expr(&Expr::lam(BinderInfo::Default, Expr::prop(), bv(1)), 0, 5);
    assert_eq!(
        binder_body(&r),
        &bv(6),
        "BVar(1) under lam should be lifted to BVar(6)"
    );

    // Π x. BVar(0) — bound, NOT lifted
    let r = tc.lift_expr(&Expr::pi(BinderInfo::Default, Expr::prop(), bv(0)), 0, 5);
    assert_eq!(
        binder_body(&r),
        &bv(0),
        "BVar(0) under Pi should NOT be lifted"
    );

    // let x = v in BVar(0) — bound, NOT lifted
    let le = Expr::let_named(Name::anon(), Expr::prop(), Expr::prop(), bv(0), false);
    let r = tc.lift_expr(&le, 0, 5);
    assert_eq!(
        binder_body(&r),
        &bv(0),
        "BVar(0) under let should NOT be lifted"
    );

    // Double nested: λ x. λ y. BVar(2) — at depth 2, BVar(2) >= 2, lifted to BVar(7)
    let inner = Expr::lam(BinderInfo::Default, Expr::prop(), bv(2));
    let outer = Expr::lam(BinderInfo::Default, Expr::prop(), inner);
    let r = tc.lift_expr(&outer, 0, 5);
    assert_eq!(
        binder_body(binder_body(&r)),
        &bv(7),
        "BVar(2) under 2 lambdas should be lifted to BVar(7)"
    );
}

#[test]
fn test_lift_expr_pi_let_cutoff_increment() {
    // Tests that lift_expr correctly increments cutoff in Pi and Let bodies
    // Mutation: cutoff + 1 -> cutoff - 1 would break lifting

    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // π x : Prop . BVar(1) - BVar(1) refers outside the pi
    // When lifting from cutoff=0 by amount=2, body processed at cutoff=1
    // BVar(1) >= 1, so lift by 2: should become BVar(3)
    let pi = Expr::pi(
        BinderInfo::Default,
        Expr::prop(),
        Expr::from_kind(ExprKind::BVar(1)),
    );
    let result = tc.lift_expr(&pi, 0, 2);
    match &result.kind {
        ExprKind::Pi(_, _, body) => {
            assert_eq!(
                body.as_ref(),
                &Expr::from_kind(ExprKind::BVar(3)),
                "BVar(1) in pi body should lift to BVar(3)"
            );
        }
        _ => panic!("Expected Pi"),
    }

    // let x = Prop in BVar(1) - similar test for Let
    let let_expr = Expr::let_named(
        Name::anon(),
        Expr::prop(),
        Expr::prop(),
        Expr::from_kind(ExprKind::BVar(1)),
        false,
    );
    let result = tc.lift_expr(&let_expr, 0, 2);
    match &result.kind {
        ExprKind::Let(_, _, _, body, _) => {
            assert_eq!(
                body.as_ref(),
                &Expr::from_kind(ExprKind::BVar(3)),
                "BVar(1) in let body should lift to BVar(3)"
            );
        }
        _ => panic!("Expected Let"),
    }

    // Bound variable should NOT be lifted
    let pi_bound = Expr::pi(
        BinderInfo::Default,
        Expr::prop(),
        Expr::from_kind(ExprKind::BVar(0)),
    );
    let result = tc.lift_expr(&pi_bound, 0, 2);
    match &result.kind {
        ExprKind::Pi(_, _, body) => {
            assert_eq!(
                body.as_ref(),
                &Expr::from_kind(ExprKind::BVar(0)),
                "BVar(0) in pi body should not be lifted"
            );
        }
        _ => panic!("Expected Pi"),
    }
}

// =========================================================================
// ZFC expression traversal: lift_expr must traverse into ZFC nodes
// =========================================================================

#[test]
fn test_lift_expr_zfc_mem_traverses_subexpressions() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // ZFCMem { element: BVar(0), set: BVar(1) } lifted at cutoff 0 by 3
    // Both BVar(0) and BVar(1) are >= 0, so both should be lifted
    let mem = Expr::from_kind(ExprKind::ZFCMem {
        element: std::sync::Arc::new(Expr::from_kind(ExprKind::BVar(0))),
        set: std::sync::Arc::new(Expr::from_kind(ExprKind::BVar(1))),
    });
    let result = tc.lift_expr(&mem, 0, 3);
    match &result.kind {
        ExprKind::ZFCMem { element, set } => {
            assert_eq!(
                element.as_ref(),
                &Expr::from_kind(ExprKind::BVar(3)),
                "ZFCMem element BVar(0) should lift to BVar(3)"
            );
            assert_eq!(
                set.as_ref(),
                &Expr::from_kind(ExprKind::BVar(4)),
                "ZFCMem set BVar(1) should lift to BVar(4)"
            );
        }
        _ => panic!("Expected ZFCMem, got {:?}", result.kind),
    }
}

#[test]
fn test_lift_expr_zfc_comprehension_increments_cutoff_for_pred() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // ZFCComprehension { domain: BVar(0), pred: BVar(0) }
    // domain at cutoff 0: BVar(0) >= 0 → lifted to BVar(3)
    // pred at cutoff 1 (binding construct): BVar(0) < 1 → NOT lifted
    let comp = Expr::from_kind(ExprKind::ZFCComprehension {
        domain: std::sync::Arc::new(Expr::from_kind(ExprKind::BVar(0))),
        pred: std::sync::Arc::new(Expr::from_kind(ExprKind::BVar(0))),
    });
    let result = tc.lift_expr(&comp, 0, 3);
    match &result.kind {
        ExprKind::ZFCComprehension { domain, pred } => {
            assert_eq!(
                domain.as_ref(),
                &Expr::from_kind(ExprKind::BVar(3)),
                "ZFCComprehension domain BVar(0) should lift to BVar(3)"
            );
            assert_eq!(
                pred.as_ref(),
                &Expr::from_kind(ExprKind::BVar(0)),
                "ZFCComprehension pred BVar(0) should NOT be lifted (bound by comprehension)"
            );
        }
        _ => panic!("Expected ZFCComprehension, got {:?}", result.kind),
    }
}

#[test]
fn test_lift_expr_zfc_set_traverses_subexpressions() {
    use crate::expr::ZFCSetExpr;

    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // ZFCSet(Singleton(BVar(0))) lifted at cutoff 0 by 2
    // BVar(0) >= 0 → lifted to BVar(2)
    let zfc_set = Expr::from_kind(ExprKind::ZFCSet(ZFCSetExpr::Singleton(
        std::sync::Arc::new(Expr::from_kind(ExprKind::BVar(0))),
    )));
    let result = tc.lift_expr(&zfc_set, 0, 2);
    match &result.kind {
        ExprKind::ZFCSet(ZFCSetExpr::Singleton(inner)) => {
            assert_eq!(
                inner.as_ref(),
                &Expr::from_kind(ExprKind::BVar(2)),
                "ZFCSet(Singleton(BVar(0))) should lift to ZFCSet(Singleton(BVar(2)))"
            );
        }
        _ => panic!("Expected ZFCSet(Singleton), got {:?}", result.kind),
    }
}

// =========================================================================
// ZFC expression traversal: abstract_fvar_in_expr must traverse ZFC nodes
// =========================================================================

#[test]
fn test_abstract_fvar_in_expr_zfc_mem() {
    use crate::tc::cert::abstract_fvar_in_expr;

    let fvar_id = FVarId(42);
    let fvar_expr = Expr::from_kind(ExprKind::FVar(fvar_id));

    // ZFCMem { element: FVar(42), set: Prop }
    // Abstracting FVar(42) at depth 0 should replace element with BVar(0)
    let mem = Expr::from_kind(ExprKind::ZFCMem {
        element: std::sync::Arc::new(fvar_expr.clone()),
        set: std::sync::Arc::new(Expr::prop()),
    });
    let result = abstract_fvar_in_expr(mem, fvar_id, 0);
    match &result.kind {
        ExprKind::ZFCMem { element, set } => {
            assert_eq!(
                element.as_ref(),
                &Expr::from_kind(ExprKind::BVar(0)),
                "FVar(42) in ZFCMem element should be abstracted to BVar(0)"
            );
            assert_eq!(
                set.as_ref(),
                &Expr::prop(),
                "Prop in ZFCMem set should be unchanged"
            );
        }
        _ => panic!("Expected ZFCMem, got {:?}", result.kind),
    }
}

#[test]
fn test_abstract_fvar_in_expr_zfc_comprehension_depth() {
    use crate::tc::cert::abstract_fvar_in_expr;

    let fvar_id = FVarId(99);
    let fvar_expr = Expr::from_kind(ExprKind::FVar(fvar_id));

    // ZFCComprehension { domain: FVar(99), pred: FVar(99) }
    // At depth 0: domain FVar(99) → BVar(0), pred FVar(99) → BVar(1) (depth+1)
    let comp = Expr::from_kind(ExprKind::ZFCComprehension {
        domain: std::sync::Arc::new(fvar_expr.clone()),
        pred: std::sync::Arc::new(fvar_expr.clone()),
    });
    let result = abstract_fvar_in_expr(comp, fvar_id, 0);
    match &result.kind {
        ExprKind::ZFCComprehension { domain, pred } => {
            assert_eq!(
                domain.as_ref(),
                &Expr::from_kind(ExprKind::BVar(0)),
                "FVar in domain should become BVar(0) at depth 0"
            );
            assert_eq!(
                pred.as_ref(),
                &Expr::from_kind(ExprKind::BVar(1)),
                "FVar in pred should become BVar(1) at depth 0+1"
            );
        }
        _ => panic!("Expected ZFCComprehension, got {:?}", result.kind),
    }
}

